// Regenerates tests/acceptance/F*.spec.ts and docs/qa/acceptance-coverage.md from the approved requirements.
// Run: node --experimental-strip-types tests/acceptance/generate.ts
// Do not edit the generated skeletons by hand: a criterion becomes a real test in the build task that owns it,
// by replacing its test.todo in the same file. The generator keeps real tests (see MERGE below).
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { featureDirs, readCriteria, repoRoot, type Criterion } from './spec-ids.ts';

const root = repoRoot();

function title(c: Criterion): string {
  const t = c.text.replace(/\s+/g, ' ').trim();
  const short = t.length <= 110 ? t : `${t.slice(0, 107).replace(/\s+\S*$/, '')} ...`;
  return `${c.id} ${short}`;
}

function render(featureDir: string, criteria: Criterion[], existing: string): string {
  const header = [
    `// ${featureDir}: acceptance check skeletons, one test.todo per criterion.`,
    `// GENERATED by tests/acceptance/generate.ts from specs/features/${featureDir}/requirements.md. Do not edit the todo lines.`,
    '// The full Given, When, Then is in the comment above each test. To write a test, replace its test.todo in the task that builds it',
    '// and keep the ID at the start of the title (tests/acceptance/coverage.spec.ts checks every criterion appears).',
    "import { describe, test } from 'vitest';",
    '',
  ];
  const groups = new Map<string, Criterion[]>();
  for (const c of criteria) groups.set(c.group, [...(groups.get(c.group) ?? []), c]);
  const body: string[] = [];
  for (const [g, items] of groups) {
    body.push(`describe(${JSON.stringify(`${featureDir.slice(0, 3)} ${g}`)}, () => {`);
    for (const c of items) {
      // MERGE: if the existing file already has a real test for this ID (not a todo), keep the file as is for that line.
      const real = new RegExp(`test(?:\\.[a-z]+)?\\(\\s*['"\`]${c.id.replace(/[/.-]/g, '\\$&')} `).test(existing) && !existing.includes(`test.todo(${JSON.stringify(title(c))})`);
      body.push(`  // ${c.text.replace(/\s+/g, ' ').trim()}`);
      body.push(real ? `  // (real test exists elsewhere in this file or was written by a build task: ${c.id})` : `  test.todo(${JSON.stringify(title(c))});`);
    }
    body.push('});', '');
  }
  return [...header, ...body].join('\n');
}

const summary: string[] = [];
const byGroup = new Map<string, string[]>();
let total = 0;
for (const d of featureDirs(root)) {
  const criteria = readCriteria(d, root);
  const file = resolve(root, 'tests', 'acceptance', `${d}.spec.ts`);
  const existing = existsSync(file) ? readFileSync(file, 'utf8') : '';
  writeFileSync(file, render(d, criteria, existing));
  const groups = new Map<string, number>();
  for (const c of criteria) {
    groups.set(c.group, (groups.get(c.group) ?? 0) + 1);
    byGroup.set(c.group, [...(byGroup.get(c.group) ?? []), `${d.slice(0, 3)}`]);
  }
  summary.push(`| ${d} | ${criteria.length} | ${[...groups].map(([g, n]) => `${g} (${n})`).join(', ')} |`);
  total += criteria.length;
}

// Hand-off ID inventory: every requirement ID in the hand-off, whether the hand-off gives an acceptance check,
// and how many approved criteria cover it.
const handoff = readFileSync(resolve(root, 'specs', 'product', 'handoff-v1.2.md'), 'utf8').split('\n');
const inventory: string[] = [];
let withoutAny = 0;
for (const line of handoff) {
  const m = /^\|\s*([A-Z]+-\d\d)\s*\|/.exec(line);
  if (!m) continue;
  const id = m[1] as string;
  const cells = line.split('|').slice(1, -1).map((c) => c.trim());
  const hasCheck = cells.length >= 3 && cells[2] !== '' && !/^Not needed/i.test(cells[2] ?? '');
  const feats = [...new Set(byGroup.get(id) ?? [])];
  const n = (byGroup.get(id) ?? []).length;
  const status = id === 'PAY-08' ? 'Deferred (F16)' : n > 0 ? 'Criteria approved' : hasCheck ? 'Hand-off check only' : 'GAP: no check and no criteria';
  if (status.startsWith('GAP')) withoutAny++;
  inventory.push(`| ${id} | ${hasCheck ? 'yes' : 'no'} | ${n > 0 ? `${n} (${feats.join(', ')})` : '0'} | ${status} |`);
}

const md = [
  '# Acceptance coverage',
  '',
  'Generated by `tests/acceptance/generate.ts` from the approved `specs/features/*/requirements.md`. Do not edit by hand.',
  'Every criterion below has one `test.todo` (or a real test) in `tests/acceptance/<feature>.spec.ts`; `tests/acceptance/coverage.spec.ts` fails if one is missing.',
  `Features with no approved requirements on this branch yet (${Array.from({ length: 16 }, (_, i) => `F${String(i + 1).padStart(2, '0')}`).filter((f) => !featureDirs(root).some((d) => d.startsWith(f))).join(', ')}) have no row.`,
  '',
  '| Feature | Criteria | Groups (requirement ID, count) |',
  '|---|---|---|',
  ...summary,
  `| **Total** | **${total}** | |`,
  '',
  '## Hand-off ID inventory',
  '',
  `${inventory.length} requirement IDs in the hand-off; **${withoutAny}** have neither a hand-off check nor approved criteria.`,
  '',
  '| ID | Hand-off check | Approved criteria (features) | Status |',
  '|---|---|---|---|',
  ...inventory,
  '',
].join('\n');
writeFileSync(resolve(root, 'docs', 'qa', 'acceptance-coverage.md'), md);
console.log(`wrote ${featureDirs(root).length} skeleton files, ${total} criteria`);
